import{_ as e,o as a,c as r,a5 as d}from"./chunks/framework.bIR-4glx.js";const y=JSON.parse('{"title":"90-Day Cycle Map","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/worksheets/90-day-cycle.en.md","filePath":"public/downloads/worksheets/90-day-cycle.en.md","lastUpdated":1795488252000}'),n={name:"public/downloads/worksheets/90-day-cycle.en.md"};function i(o,t,s,h,l,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="_90-day-cycle-map" tabindex="-1">90-Day Cycle Map <a class="header-anchor" href="#_90-day-cycle-map" aria-label="Permalink to &quot;90-Day Cycle Map&quot;">​</a></h1><p>This sheet manages one cycle; it is not a test of daily discipline. Keep one main question each week, one input, one output, and one transfer test. When health, work, or relationships change, adjust the plan&#39;s weight first. Do not include passwords, IDs, client data, sensitive health information, or unauthorised third-party details.</p><p>This sheet owns cycle direction and phase gates, not every detail: the <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a> explains results, the <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a> maintains weekly rhythm, and <a href="https://byoungd.github.io/up/en/templates/learning-state" target="_blank" rel="noreferrer">Learning State</a> carries cross-session handover.</p><h2 id="_1-cycle-commitment" tabindex="-1">1. Cycle commitment <a class="header-anchor" href="#_1-cycle-commitment" aria-label="Permalink to &quot;1. Cycle commitment&quot;">​</a></h2><h3 id="_90-day-cycle-—-yyyy-mm-dd-to-yyyy-mm-dd" tabindex="-1">90-Day Cycle — YYYY-MM-DD to YYYY-MM-DD <a class="header-anchor" href="#_90-day-cycle-—-yyyy-mm-dd-to-yyyy-mm-dd" aria-label="Permalink to &quot;90-Day Cycle — YYYY-MM-DD to YYYY-MM-DD&quot;">​</a></h3><p>Real context:<br> Deliverable by day 90:<br> Completion standard:<br> Three core pieces of evidence:<br> Weekly time and boundaries:<br> What must be reduced or paused:</p><h2 id="_2-day-one-baseline" tabindex="-1">2. Day-one baseline <a class="header-anchor" href="#_2-day-one-baseline" aria-label="Permalink to &quot;2. Day-one baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Current evidence</th><th>Largest barrier</th><th>Planned treatment</th></tr></thead><tbody><tr><td>What I can do independently</td><td></td><td></td><td></td></tr><tr><td>Situation where I will use it</td><td></td><td></td><td></td></tr><tr><td>Materials, tools, and people available</td><td></td><td></td><td></td></tr><tr><td>Sleep, energy, and responsibility boundaries</td><td></td><td></td><td></td></tr></tbody></table><p>Keep one sample made without AI doing the task: a recording, short text, reading reconstruction, code, presentation, or real conversation note.</p><h2 id="_3-gates-for-three-phases" tabindex="-1">3. Gates for three phases <a class="header-anchor" href="#_3-gates-for-three-phases" aria-label="Permalink to &quot;3. Gates for three phases&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phase</th><th>Dates</th><th>Question to answer</th><th>Evidence to enter the next phase</th></tr></thead><tbody><tr><td>Calibrate</td><td>Days 1–14</td><td>What exactly am I training, and what is the bottleneck?</td><td>Baseline, three error categories, one stable time slot</td></tr><tr><td>Stack</td><td>Days 15–56</td><td>Which action is becoming stable under which conditions?</td><td>At least four comparable outputs and one external feedback</td></tr><tr><td>Ship</td><td>Days 57–90</td><td>Can a new listener, topic, or user still use the result?</td><td>Independent, revised, and real-delivery versions</td></tr></tbody></table><p>Without evidence for a gate, do not raise difficulty automatically. Shrink the task or repair prerequisites first.</p><h2 id="_4-twelve-weekly-questions" tabindex="-1">4. Twelve weekly questions <a class="header-anchor" href="#_4-twelve-weekly-questions" aria-label="Permalink to &quot;4. Twelve weekly questions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Week</th><th>One question only</th><th>Input evidence</th><th>Output evidence</th><th>Feedback/transfer</th></tr></thead><tbody><tr><td>1</td><td></td><td></td><td></td><td></td></tr><tr><td>2</td><td></td><td></td><td></td><td></td></tr><tr><td>3</td><td></td><td></td><td></td><td></td></tr><tr><td>4</td><td></td><td></td><td></td><td></td></tr><tr><td>5</td><td></td><td></td><td></td><td></td></tr><tr><td>6</td><td></td><td></td><td></td><td></td></tr><tr><td>7</td><td></td><td></td><td></td><td></td></tr><tr><td>8</td><td></td><td></td><td></td><td></td></tr><tr><td>9</td><td></td><td></td><td></td><td></td></tr><tr><td>10</td><td></td><td></td><td></td><td></td></tr><tr><td>11</td><td></td><td></td><td></td><td></td></tr><tr><td>12</td><td></td><td></td><td></td><td></td></tr></tbody></table><p>Write an observable question such as “Can I explain project risk in English without a script and handle one follow-up?” Do not write “be better this week”.</p><h2 id="_5-evidence-chain" tabindex="-1">5. Evidence chain <a class="header-anchor" href="#_5-evidence-chain" aria-label="Permalink to &quot;5. Evidence chain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Date</th><th>Evidence card/tool</th><th>Location kept</th><th>Result or error</th><th>Next variable</th></tr></thead><tbody><tr><td></td><td>Listening / Reading / Speaking / Writing / Life Practice</td><td></td><td></td><td></td></tr></tbody></table><p>Chat logs, playback time, and check-in screenshots are process traces. Key judgments should return to artifacts, recordings, reader/user feedback, and performance under a new condition; use the <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a> when comparing all four time points.</p><h2 id="_6-interruption-and-recovery" tabindex="-1">6. Interruption and recovery <a class="header-anchor" href="#_6-interruption-and-recovery" aria-label="Permalink to &quot;6. Interruption and recovery&quot;">​</a></h2><p>Interruption fact (no character judgment):<br> Main resistance: time / difficulty / energy / environment / responsibility<br> Task reduced to:<br> Smallest output possible within 24 hours:<br> Work I will not repay:<br> Review date:</p><p>Do not stay up late to repay missed work or rewrite the 90 days after one failure. When the same barrier appears three times, record capacity and resistance in the <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a>, then change the system condition instead of demanding more force.</p><h2 id="_7-day-ninety-review" tabindex="-1">7. Day-ninety review <a class="header-anchor" href="#_7-day-ninety-review" aria-label="Permalink to &quot;7. Day-ninety review&quot;">​</a></h2><p>Final delivery:<br> What genuinely changed from the baseline:<br> Errors that still recur:<br> What a real reader/user said:<br> Cost that proved unsustainable:<br> One habit to keep next cycle:<br> One entry point to stop next cycle:</p><p>Related chapters: <a href="https://byoungd.github.io/up/threads/part-5/90-day-plan" target="_blank" rel="noreferrer">90-Day Action Plan: Return Your Life to Yourself</a> | <a href="https://byoungd.github.io/up/en/templates/evidence-chain" target="_blank" rel="noreferrer">Evidence Chain Template</a> | <a href="https://byoungd.github.io/up/en/templates/rhythm-ledger" target="_blank" rel="noreferrer">Rhythm Ledger</a></p><hr><p>Source: <a href="https://byoungd.github.io/up/en/templates/90-day-cycle" target="_blank" rel="noreferrer">Still Here</a> · Manuscript updated: 2026-09-01. Content: <a href="https://creativecommons.org/licenses/by-nc/4.0/" target="_blank" rel="noreferrer">CC BY-NC 4.0</a>.</p>',26)])])}const u=e(n,[["render",i]]);export{y as __pageData,u as default};
